fn put(o:&mut[u8],p:usize,x:f64){o[p..p+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle]
pub unsafe extern "C" fn jacobi_iteration_method(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<2||n>26{return -1}let a=std::slice::from_raw_parts(v,n);let(d,it)=(a[0],a[1]);if !(2..=4).contains(&d)||!(1..=8).contains(&it)||n!=2+(d*d+2*d)as usize{return -1}let d=d as usize;let rhs=2+d*d;let ini=rhs+d;let(mut m,mut b,mut x,mut y)=([[0.0;4];4],[0.0;4],[0.0;4],[0.0;4]);for i in 0..d{let mut off=0.0;for j in 0..d{let z=a[2+i*d+j];if !(0..=4000).contains(&z){return -1}m[i][j]=z as f64/1000.0;if i!=j{off+=m[i][j];}}if m[i][i]<=off{return -1}if !(-2000..=2000).contains(&a[rhs+i])||!(-2000..=2000).contains(&a[ini+i]){return -1}b[i]=a[rhs+i]as f64/1000.0;x[i]=a[ini+i]as f64/1000.0;}let bytes=d*8;if out.is_null()||cap<bytes{return -2}for _ in 0..it{for i in 0..d{let mut sum=0.0;for j in 0..d{if i!=j{sum+=-m[i][j]*x[j];}}y[i]=(sum+b[i])/m[i][i];}x=y;}let z=std::slice::from_raw_parts_mut(out,bytes);for i in 0..d{put(z,i*8,x[i]);}bytes as i64}
